sp_page.css:
body,
.sp-page-root,
.container,
.container-fluid {

background:
linear-gradient(
180deg,
#F3F6FB 0%,
#EDF2F8 100%
);

padding-top:0 !important;

padding-left:0 !important;

padding-right:0 !important;

max-width:100% !important;

}



/* ROW CONTROL */

.sp-row{

margin-top:10px !important;

margin-bottom:10px !important;

margin-left:0 !important;

margin-right:0 !important;

padding:0 !important;

}



/* COLUMN CONTROL */

.sp-column{

padding-top:0 !important;

padding-bottom:0 !important;

margin-top:0 !important;

margin-bottom:10px !important;

}



/* DEFAULT WIDGET SPACING */

.sp-widget{

margin-bottom:10px !important;

}



/* BOOTSTRAP ROW */

.row{

margin-top:0 !important;

margin-bottom:0 !important;

}



/* HERO → STATS */

.hero{

margin-bottom:10px !important;

}

.hero-wrapper{

margin-bottom:10px !important;

}



/* STATS → RECENT JOINEES */

.metrics-grid{

margin-bottom:10px !important;

}



/* RECENT CARD */

.recent-card{

margin-top:10px !important;

}



/* FOOTER */

.footer-wrap{

margin-top:0 !important;

}

/* REMOVE COLUMN INNER SPACE */

.sp-column{

padding-left:0 !important;

padding-right:0 !important;

}
